const minOps = Number($('Set Prospect Domains').first()?.json?.minOpportunities ?? 1);

const PITCH_LABELS = {
  MISSING_META_PIXEL_ON_ECOMMERCE: 'Missing Meta Pixel on e-commerce store',
  ECOMMERCE_WITHOUT_EMAIL_MARKETING_CRM: 'E-commerce store without email/CRM automation',
  NO_WEB_ANALYTICS_DETECTED: 'No web analytics detected',
  NO_PAID_AD_PIXELS_DETECTED: 'No paid ad pixels installed',
  AD_PIXELS_WITHOUT_DETECTED_CMP_BANNER: 'Running ad pixels without detected consent banner',
  MISSING_LLMS_TXT_FOR_AI_SEARCH: 'Missing /llms.txt for AI search visibility',
  AI_SEARCH_CRAWLERS_BLOCKED_IN_ROBOTS: 'Blocking AI search crawlers in robots.txt',
  MISSING_DMARC_EMAIL_SECURITY: 'Missing DMARC email authentication record',
  MISSING_SPF_EMAIL_SECURITY: 'Missing SPF record',
  SSL_CERTIFICATE_EXPIRING_SOON: 'SSL certificate expiring within 21 days',
  INVALID_OR_MISSING_SSL_CERTIFICATE: 'Invalid or missing SSL certificate',
  HOMEPAGE_SET_TO_NOINDEX: 'Homepage accidentally set to noindex',
  MISSING_JSON_LD_STRUCTURED_DATA: 'Missing JSON-LD structured schema',
  WEAK_HTTP_SECURITY_HEADERS: 'Weak HTTP security headers (<50/100)',
  SLOW_SERVER_TTFB_OVER_1500MS: 'Slow server TTFB (>1.5s)'
};

const auditsByDomain = {};
const qualifiedDomains = [];

for (const item of $input.all()) {
  const row = item.json;
  if (!row || row.status !== 'analyzed' || !row.domain) continue;

  const ops = Array.isArray(row.salesOpportunities) ? row.salesOpportunities : [];
  if (ops.length < minOps) continue;

  const domainKey = String(row.domain).toLowerCase().trim();
  if (auditsByDomain[domainKey]) continue;

  const readablePitch = ops
    .slice(0, 3)
    .map((flag) => PITCH_LABELS[flag] || flag)
    .join('; ');

  auditsByDomain[domainKey] = {
    domain: domainKey,
    finalUrl: row.finalUrl || null,
    cms: row.cms || null,
    ecommercePlatform: row.ecommercePlatform || null,
    hostingOrCdn: row.hostingOrCdn || null,
    technologyCount: row.technologyCount ?? 0,
    adPixels: row.marketingSignals?.adPixels || [],
    crmTools: row.marketingSignals?.crmTools || [],
    seoScore: row.seo?.seoScore ?? null,
    geoReadinessScore: row.geo?.geoReadinessScore ?? null,
    hasLlmsTxt: row.geo?.hasLlmsTxt ?? null,
    blockedAiBots: row.geo?.blockedAiBots || [],
    sslDaysUntilExpiry: row.ssl?.daysUntilExpiry ?? null,
    hasDmarc: row.dns?.hasDmarc ?? null,
    salesOpportunities: ops,
    pitchSummary: readablePitch
  };
  qualifiedDomains.push(domainKey);
}

if (qualifiedDomains.length === 0) {
  return [];
}

return [{
  json: {
    domains: qualifiedDomains,
    qualifiedCount: qualifiedDomains.length,
    auditsByDomain
  }
}];

const auditsByDomain = $('Qualify Agency Leads (Filter Sales Opportunities)').first()?.json?.auditsByDomain || {};
const output = [];

for (const item of $input.all()) {
  const lead = item.json;
  if (!lead || lead.status !== 'enriched' || !lead.domain) continue;

  const domainKey = String(lead.domain).toLowerCase().trim();
  const audit = auditsByDomain[domainKey] || {};

  const verifiedDms = Array.isArray(lead.decisionMakers)
    ? lead.decisionMakers.filter((dm) => dm && dm.verifiedForBilling === true && dm.email)
    : [];

  const baseFields = {
    domain: domainKey,
    companyName: lead.companyName || domainKey,
    cms: audit.cms ?? null,
    ecommercePlatform: audit.ecommercePlatform ?? null,
    technologyCount: audit.technologyCount ?? 0,
    seoScore: audit.seoScore ?? null,
    geoReadinessScore: audit.geoReadinessScore ?? null,
    hasLlmsTxt: audit.hasLlmsTxt ?? null,
    blockedAiBots: (audit.blockedAiBots || []).join(', '),
    sslDaysUntilExpiry: audit.sslDaysUntilExpiry ?? null,
    salesOpportunities: (audit.salesOpportunities || []).join(', '),
    pitchSummary: audit.pitchSummary || '',
    emailProvider: lead.dns?.emailProvider || null,
    hasMx: lead.dns?.hasMx ?? false,
    hasDmarc: lead.dns?.hasDmarc ?? false,
    primaryPhone: Array.isArray(lead.phones) && lead.phones.length > 0 ? lead.phones[0] : null,
    companyLinkedin: lead.socials?.linkedin || null,
    extractedAtUtc: lead.extractedAtUtc || null
  };

  if (verifiedDms.length > 0) {
    for (const dm of verifiedDms) {
      output.push({
        json: {
          ...baseFields,
          contactType: 'verified_decision_maker',
          contactName: dm.fullName,
          contactRole: dm.role,
          contactEmail: dm.email,
          contactLinkedin: dm.linkedinUrl || null,
          emailSource: dm.emailSource,
          sourceUrl: dm.sourceUrl || lead.sourceUrl || null,
          confidence: dm.confidence
        }
      });
    }
  } else if (lead.primaryEmail) {
    output.push({
      json: {
        ...baseFields,
        contactType: 'company_primary_email',
        contactName: null,
        contactRole: null,
        contactEmail: lead.primaryEmail,
        contactLinkedin: null,
        emailSource: 'published_company_email',
        sourceUrl: lead.sourceUrl || null,
        confidence: lead.confidence ?? 0
      }
    });
  }
}

return output;
